import sys, inspect, importlib, glob, os, re
sys.path.insert(0, '/app/categorizationapp')
import pandas as pd
from categorizationapp.UtilityScripts import AppUtil

def bank_funcs():
    out = {}
    for path in sorted(glob.glob('/app/categorizationapp/categorizationapp/BankScripts/*.py')):
        mod_name = os.path.basename(path)[:-3]
        if mod_name == '__init__':
            continue
        mod = importlib.import_module('categorizationapp.BankScripts.' + mod_name)
        for name, fn in vars(mod).items():
            if name.startswith('categorize_') and inspect.isfunction(fn):
                out[mod_name] = fn
    return out

def run(fn, rows, accountType="SAVING", accountHolder="TEST HOLDER"):
    df = pd.DataFrame(rows)
    for col, default in [("remark", ""), ("balanceAfterTransaction", 1000.0),
                         ("amount", 100.0), ("type", "DEBIT"), ("description", "")]:
        if col not in df.columns:
            df[col] = default
    df = AppUtil.clean_input_df(df)
    n = len(inspect.signature(fn).parameters)
    out = fn(df, accountType, accountHolder) if n == 3 else fn(df, accountType)
    return out

