import ast, glob, os, itertools
def conjuncts(node):
    # split on BitAnd
    if isinstance(node, ast.BinOp) and isinstance(node.op, ast.BitAnd):
        return conjuncts(node.left) + conjuncts(node.right)
    return [ast.unparse(node)]

for path in sorted(glob.glob('BankScripts/*.py') + glob.glob('UtilityScripts/*.py')):
    tree = ast.parse(open(path).read())
    for node in ast.walk(tree):
        if isinstance(node, ast.Assign) and any(getattr(t,'id',None)=='conditions_choices' for t in node.targets):
            items = node.value.elts if isinstance(node.value, ast.List) else []
            rules=[]
            for it in items:
                if isinstance(it, ast.List) and len(it.elts)==2:
                    rules.append((it.lineno, it.elts[0], ast.unparse(it.elts[1])))
            for (i,(l1,c1,ch1)),(j,(l2,c2,ch2)) in itertools.combinations(list(enumerate(rules)),2):
                s1, s2 = set(conjuncts(c1)), set(conjuncts(c2))
                if s1 <= s2:
                    tag = "DUP" if s1==s2 else "SHADOW"
                    print(f"{tag} {path}:{l2} shadowed by :{l1}  choice1={ch1[:35]!r} choice2={ch2[:35]!r}")
