import ast, glob, re
pats=[]
for path in sorted(glob.glob('BankScripts/*.py') + glob.glob('UtilityScripts/*.py')):
    src=open(path).read()
    tree=ast.parse(src)
    for node in ast.walk(tree):
        if isinstance(node, ast.Constant) and isinstance(node.value,str):
            pats.append((path,node.lineno,node.value))
sus=[]
for path,ln,p in pats:
    if re.search(r'\[[^\]]*\{[^\]]*\]', p):   # brace inside char class
        sus.append(("BRACE-IN-CLASS",path,ln,p))
    if re.search(r'\$.', p) and not re.search(r'\$\|', p) and '$' in p[:-1]:
        # $ not at end and not before |
        pass
    try:
        re.compile(p)
    except Exception as e:
        sus.append(("BADREGEX",path,ln,p))
for s in sus: print(s[0], f"{s[1]}:{s[2]}", repr(s[3])[:120])
